import sqlite3

def handle(query, state):
    flag = state.get("flag", "")
    search_term = (query.get("q") or [""])[0]

    conn = sqlite3.connect(":memory:")
    cur = conn.cursor()

    cur.execute(
        "CREATE TABLE articles (id INTEGER PRIMARY KEY, title TEXT, author TEXT, content TEXT)"
    )
    cur.execute(
        "CREATE TABLE secrets (id INTEGER PRIMARY KEY, type TEXT, value TEXT)"
    )
    cur.executemany(
        "INSERT INTO articles (title, author, content) VALUES (?, ?, ?)",
        [
            ("SQL Tips", "alice", "Learn SQL optimization"),
            ("Database Design", "bob", "Schema best practices"),
            ("Security", "charlie", "Protect your data"),
            ("Performance", "alice", "Index strategies"),
        ],
    )
    cur.execute(
        "INSERT INTO secrets (type, value) VALUES (?, ?)",
        ("admin_token", flag),
    )
    conn.commit()

    sql = "SELECT id, title, author FROM articles WHERE content LIKE '%" + search_term + "%'"
    try:
        cur.execute(sql)
        rows = cur.fetchall()
    except sqlite3.Error as e:
        conn.close()
        return 500, {"Content-Type": "text/plain"}, "DB error: " + str(e)

    conn.close()

    if not rows:
        return 200, {"Content-Type": "text/plain"}, "No articles found."

    lines = []
    for row in rows:
        lines.append("|".join(str(c) for c in row))
    return 200, {"Content-Type": "text/plain"}, "\n".join(lines)
